// Initialize flow context for DOMAIN domain
flow.set('DOMAIN_state', {
    initialized: true,
    timestamp: new Date().toISOString(),
    devices: {},
    lastCommand: null,
    commandHistory: []
});

node.log('DOMAIN domain initialized');

return msg;

// Utility function to format timestamps
const formatTimestamp = (iso) => {
    if (!iso) return 'Never';
    const date = new Date(iso);
    const now = new Date();
    const diff = Math.floor((now - date) / 1000);

    if (diff < 60) return `${diff}s ago`;
    if (diff < 3600) return `${Math.floor(diff/60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff/3600)}h ago`;
    return `${Math.floor(diff/86400)}d ago`;
};

msg.formattedTime = formatTimestamp(msg.payload.timestamp);
return msg;

// Utility function to validate command structure
const requiredFields = ['action', 'timestamp'];

for (const field of requiredFields) {
    if (!msg.payload[field]) {
        msg.error = `Missing required field: ${field}`;
        return [null, msg]; // Send to error output
    }
}

// Add request ID if not present
if (!msg.payload.request_id) {
    msg.payload.request_id = `${msg.payload.action}-${Date.now()}`;
}

return [msg, null]; // Send to success output
